import React, {useState} from 'react';
import './SearchBar.css'
import Result from "./Homepage/Header/Result";

function SearchBar(props) {
    const {professorList, onChangeProfessor, isHome} = props;
    const [search, setSearch] = useState('');
    const handleChange = event => {
        setSearch(event.target.value);
    };

    const filteredListLower = professorList
        .filter(listItem => listItem.name.toLowerCase().includes(search.toLowerCase()));


    let professorDetails;

    if (filteredListLower.length > 0) {
        professorDetails = (
            <React.Fragment>
                <div>
                    {
                        filteredListLower
                            .map((x) => {
                                return <Result key={x.id} professor={x} onChangeProfessor={onChangeProfessor}/>
                            })
                    }
                </div>
            </React.Fragment>
        )
    } else {
        professorDetails = (
            <div className={"result"}>Non ci sono professori con questo nome</div>)
    }

    if(isHome){
        return (
            <>
                <div>
                    <div className={'search-bar-container'}>
                        {/*<img src={imgStart} className={'img-start'} alt={imgStart}/>*/}

                        <input className={"search-input"}
                               type="text"
                               value={search}
                               autoCapitalize = "none"
                               placeholder={"Cerca un professore..."}
                               onChange={handleChange}
                        />
                        <div className={'search-bar'}>
                            {
                                search ? professorDetails : null
                            }
                        </div>

                    </div>
                </div>

            </>
        );
    } else {
        return (
            <>
                <div>
                    <div className={'search-bar-container'}>
                        {/*<img src={imgStart} className={'img-start'} alt={imgStart}/>*/}

                        <input className={"search-input"}
                               type="text"
                               value={search}
                               autoCapitalize = "none"
                               placeholder={"Cerca un professore..."}
                               onChange={handleChange}
                        />
                        <div className={'search-bar'}>
                            {
                                search ? professorDetails : null
                            }
                        </div>

                    </div>
                </div>

            </>
        );
    }
}

export default SearchBar;
